def create
  Voucher::BatchCreateVouchers.call(
    params[:qty], correct_in(params).permit(:product_type, :tag, :country)
  ).on do |result|
    result.success {|success| render json: decorate(success.records) }
    result.errors {|errors| render json: {errors: correct_out(errors.as_json)}, status: :unprocessable_entity }
  end
end

def global
  @global ||= GroupedStats.new(
    ::Voucher::Voucher.count,
    ::Voucher::Voucher.claimed.count
  )
end

def by_product
  @by_product ||= grouped(
    ::Voucher::Voucher.group(:product_type).order(:product_type),
    transform_keys: lambda do |types|
      types.to_h {|type| [type, type] }
    end
  )
end

def by_tag
  @by_tag ||= grouped(
    ::Voucher::Voucher.group(:tag).order(:tag),
    transform_keys: lambda do |tags|
      tags.to_h {|tag| [tag, tag] }
    end
  )
end
